// VerifyEmail is the resolver for the VerifyEmail field.
func (r *mutationResolver) VerifyEmail(ctx context.Context, token string) (bool, error) {
    user, err := r.UserService.FindByVerificationToken(token)
    if err != nil {
        return false, fmt.Errorf("invalid or expired verification token")
    }

    user.IsVerified = true
    user.VerificationToken = ""
    
    if err := r.UserService.Update(user); err != nil {
        return false, fmt.Errorf("failed to verify identity: %v", err)
    }

    return true, nil
}

// Enable2fa is the resolver for the Enable2FA field.
func (r *mutationResolver) Enable2fa(ctx context.Context) (string, error) {
	userID, err := utils.GetUserIDFromContext(ctx)
	if err != nil {
		return "", err
	}

	user, err := r.UserService.FindByID(userID)
	if err != nil {
		return "", fmt.Errorf("user not found")
	}

	// Generate encrypted TOTP secret
	key, err := totp.Generate(totp.GenerateOptions{
		Issuer:      "Balej",
		AccountName: user.Email,
	})
	if err != nil {
		return "", fmt.Errorf("failed to generate 2FA secret")
	}

	user.TwoFactorSecret = key.Secret()
	user.TwoFactorEnabled = true // Enable it immediately for demo; or wait for verification
	
	if err := r.UserService.Update(user); err != nil {
		return "", fmt.Errorf("failed to sync 2FA node: %v", err)
	}

	return key.Secret(), nil
}

