// SendRTCSignal is the resolver for the SendRTCSignal field.
func (r *mutationResolver) SendRTCSignal(ctx context.Context, chatID string, signal string, typeArg string) (bool, error) {
	userID, err := utils.GetUserIDFromContext(ctx)
	if err != nil {
		return false, err
	}

	rtcSignal := &model.RTCSignal{
		Signal:   signal,
		Type:     typeArg,
		SenderID: int32(userID),
	}

	r.PubSub.Publish("rtc:"+chatID, rtcSignal)
	return true, nil
}

// RtcSignalSent is the resolver for the rtcSignalSent field.
func (r *subscriptionResolver) RtcSignalSent(ctx context.Context, chatID string) (<-chan *model.RTCSignal, error) {
	signalChan := make(chan *model.RTCSignal, 1)
	genChan := make(chan interface{}, 1)

	go func() {
		for {
			select {
			case <-ctx.Done():
				return
			case data, ok := <-genChan:
				if !ok {
					return
				}
				if s, ok := data.(*model.RTCSignal); ok {
					signalChan <- s
				}
			}
		}
	}()

	err := r.PubSub.Subscribe("rtc:"+chatID, genChan)
	if err != nil {
		return nil, err
	}

	return signalChan, nil
}

func (r *mutationResolver) GenerateSecureJobLink(ctx context.Context, jobID string) (string, error) {
	userID, err := utils.GetUserIDFromContext(ctx)
	if err != nil {
		return "", err
	}

	token, err := r.SecureRelayService.GenerateToken(jobID, userID)
	if err != nil {
		return "", fmt.Errorf("failed to create secure relay: %v", err)
	}

	frontendURL := os.Getenv("FRONTEND_URL")
	if frontendURL == "" {
		frontendURL = "http://localhost:3000"
	}

	return fmt.Sprintf("%s/jobs/secure/%s", frontendURL, token), nil
}

func (r *mutationResolver) VerifySecureJobLink(ctx context.Context, token string) (*model.JobOffer, error) {
	jobIDStr, err := r.SecureRelayService.VerifyToken(token)
	if err != nil {
		return nil, err
	}

	id, _ := strconv.ParseUint(jobIDStr, 10, 32)
	job, err := r.JobService.FindByID(uint(id))
	if err != nil {
		return nil, fmt.Errorf("job node not found: %v", err)
	}

	return &model.JobOffer{
		JobID:       strconv.Itoa(int(job.ID)),
		Title:       job.Title,
		Description: job.Description,
		Location:    job.Location,
		SalaryRange: &job.SalaryRange,
	}, nil
}

// Mutation returns MutationResolver implementation.
func (r *Resolver) Mutation() MutationResolver { return &mutationResolver{r} }

// Query returns QueryResolver implementation.
func (r *Resolver) Query() QueryResolver { return &queryResolver{r} }

// Subscription returns SubscriptionResolver implementation.
func (r *Resolver) Subscription() SubscriptionResolver { return &subscriptionResolver{r} }

type mutationResolver struct{ *Resolver }
type queryResolver struct{ *Resolver }
type subscriptionResolver struct{ *Resolver }
